/**
 * §12 (requests): a death, reported.
 *
 * The densest and most-read prose in the run, and the register it was written
 * in — the merchandise printed that morning, the escort who will hear the name
 * read back, the echo outliving the alliance — made every one of them the same
 * length and the same shape, which is the opposite of what a death should read
 * like. Each line now carries the facts the pool exists to carry (who, where,
 * what killed them, who saw it, how old they were) and stops there.
 *
 * The keyed pools stay: a twelve-year-old dying of exposure, a Career bleeding
 * out and a fan favourite drowning are different events and the log should say
 * which one it is. See `pickDeathPool` in `engine/combat.ts`.
 */
