/**
 * §12 (requests): a parachute, reported.
 *
 * The second most-drawn pool in the simulation at ~16 a run, and it was where
 * the register was doing the least work: thirty-one different ways of saying
 * that silver came down, most of them ending on a remark about the Capitol.
 * What the reader needs is who it was for, what was in it, and where it
 * landed, and what varies between lines is the *circumstance* of the delivery
 * — which is now the only thing that varies.
 */
