/**
 * Grief, vengeance and relief. A cannon reshapes everyone still breathing —
 * these are the lines that let the feed show it instead of only tallying it.
 */
/**
 * §12/§22 (requests): plain, and everybody named.
 *
 * These three pools are the highest-traffic prose in the simulation — a run
 * draws from them thirteen, twelve and one times respectively — and they were
 * the most editorial writing in the repository: most lines spent their second
 * sentence telling the reader how to feel about the first, and a measured 261
 * of them named only one of the two or three tributes the line was actually
 * about. Both are the same failure. A chronicle is a record of what happened,
 * and a record that will not say who was in the room is not one.
 *
 * So: one fact per line, stated once, with every participant named. No line
 * interprets, and no line refers to a tribute as "somebody".
 */
