/**
 * §12 (requests): the border, reported. The telegraph says which sector and
 * when; the collapse says who was in it, what it cost and where they got to.
 *
 * §25: both carry a stable marker — `BORDER WARNING:` and `BORDER COLLAPSE:` —
 * the way `AMBUSH:` and `GROUP FIGHT:` already do. The collapse had one and the
 * warning did not, which meant the soak counted telegraphs by matching a
 * fragment of one line's prose ('border will close around') and silently
 * measured zero the moment that line was reworded. A marker is something the
 * reader can scan for and something a counter can key on without reading
 * English.
 */
